:root {
  --bg: #1a1c2c;
  --card: #2d2f45;
  --text: #f4f4f4;
  --accent: #ffcd75;
  --accent-hover: #ffe08a;
  --muted: #a0a0b0;
  --danger: #e86a6a;
  --border: #4a4d6a;
  font-size: 16px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: 'Courier New', monospace;
  color: var(--text);
  padding: 1rem;
}

.app {
  background: var(--card);
  border: 4px solid var(--border);
  border-radius: 0;
  padding: 1.5rem;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 0 0 4px var(--bg), 0 0 0 8px var(--border);
}

h1 {
  margin: 0 0 1rem;
  font-size: 1.75rem;
  text-align: center;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--border);
}

.input-row {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

#todo-input {
  flex: 1;
  padding: 0.75rem;
  font-family: inherit;
  font-size: 1rem;
  background: var(--bg);
  border: 3px solid var(--border);
  color: var(--text);
  outline: none;
}

#todo-input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}

#todo-add {
  padding: 0.75rem 1.25rem;
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  background: var(--accent);
  color: var(--bg);
  border: 3px solid var(--border);
  cursor: pointer;
  text-transform: uppercase;
  transition: background 0.1s, transform 0.1s;
}

#todo-add:hover {
  background: var(--accent-hover);
}

#todo-add:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

#todo-add:active {
  transform: translate(2px, 2px);
}

.counts {
  display: flex;
  justify-content: space-between;
  font-size: 0.9rem;
  color: var(--muted);
  margin-bottom: 1rem;
  padding-bottom: 0.5rem;
  border-bottom: 2px dashed var(--border);
}

.counts span span {
  color: var(--accent);
  font-weight: bold;
}

.todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--bg);
  border: 3px solid var(--border);
  padding: 0.5rem;
}

.todo-item input[type="checkbox"] {
  width: 1.25rem;
  height: 1.25rem;
  accent-color: var(--accent);
  cursor: pointer;
  flex-shrink: 0;
}

.todo-item input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.todo-item .todo-text {
  flex: 1;
  font-size: 1rem;
  word-break: break-word;
}

.todo-item .todo-text.done {
  text-decoration: line-through;
  color: var(--muted);
}

.todo-item button {
  background: transparent;
  border: 2px solid var(--danger);
  color: var(--danger);
  font-family: inherit;
  font-size: 0.9rem;
  padding: 0.25rem 0.5rem;
  cursor: pointer;
  transition: background 0.1s, color 0.1s;
}

.todo-item button:hover {
  background: var(--danger);
  color: var(--text);
}

.todo-item button:focus-visible {
  outline: 2px solid var(--danger);
  outline-offset: 2px;
}

.todo-item button:active {
  transform: translate(1px, 1px);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .app {
    padding: 1rem;
  }
  h1 {
    font-size: 1.4rem;
  }
  .input-row {
    flex-direction: column;
  }
  #todo-add {
    width: 100%;
  }
}

let nextId = 1;
let tasks = [];

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');

function updateCounts() {
  totalEl.textContent = String(tasks.length);
  const incomplete = tasks.filter(t => !t.done).length;
  remainingEl.textContent = String(incomplete);
}

function createTaskElement(task) {
  const li = document.createElement('li');
  li.className = 'todo-item';

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.id = `todo-check-${task.id}`;
  checkbox.checked = task.done;
  checkbox.setAttribute('aria-label', `Mark task ${task.id} as ${task.done ? 'incomplete' : 'complete'}`);
  checkbox.addEventListener('change', () => {
    task.done = checkbox.checked;
    textSpan.classList.toggle('done', task.done);
    checkbox.setAttribute('aria-label', `Mark task ${task.id} as ${task.done ? 'incomplete' : 'complete'}`);
    updateCounts();
  });

  const textSpan = document.createElement('span');
  textSpan.className = 'todo-text';
  textSpan.id = `todo-text-${task.id}`;
  textSpan.textContent = task.text;
  if (task.done) textSpan.classList.add('done');

  const label = document.createElement('label');
  label.htmlFor = checkbox.id;
  label.className = 'sr-only';
  label.textContent = `Complete task: ${task.text}`;

  const delBtn = document.createElement('button');
  delBtn.type = 'button';
  delBtn.id = `todo-delete-${task.id}`;
  delBtn.textContent = 'Delete';
  delBtn.setAttribute('aria-label', `Delete task: ${task.text}`);
  delBtn.addEventListener('click', () => {
    tasks = tasks.filter(t => t.id !== task.id);
    li.remove();
    updateCounts();
  });

  li.appendChild(checkbox);
  li.appendChild(label);
  li.appendChild(textSpan);
  li.appendChild(delBtn);
  return li;
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;

  const task = { id: nextId++, text, done: false };
  tasks.push(task);
  list.appendChild(createTaskElement(task));
  input.value = '';
  input.focus();
  updateCounts();
}

addBtn.addEventListener('click', addTask);
input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    addTask();
  }
});

updateCounts();
